<template>
  <PageHero
    tag="Company Blog"
    title="会社ブログ"
    subtitle="技術・開発・チームの取り組みを発信しています"
  />

  <!-- ===== Blog Posts ===== -->
  <section class="blog-section">
    <v-container>
      <div class="posts-grid">
        <router-link
          v-for="(post, i) in posts"
          :key="post.id"
          :to="{ name: 'blog-detail', params: { id: post.id } }"
          class="post-card"
          :class="{ reveal: post.id !== activeId }"
          :style="{ '--reveal-i': i % 3 }"
          v-reveal
          @click="activeId = post.id"
        >
          <!-- 共有要素トランジションの対象は 1 枚だけ（同名が 2 つあると遷移全体が skip される）。
               対象カードは .reveal を外して、画面外でもモーフ先が透明にならないようにする -->
          <div
            class="post-thumbnail"
            :style="{
              background: post.thumbColor,
              viewTransitionName: post.id === activeId ? 'blog-cover' : undefined,
            }"
          >
            <v-icon size="40" class="thumb-icon">{{ post.icon }}</v-icon>
          </div>
          <div class="post-body">
            <div class="post-meta">
              <span class="post-category">{{ post.category }}</span>
              <span class="post-date">{{ formatMonthJa(post.date) }}</span>
            </div>
            <h2 class="post-title">{{ post.title }}</h2>
            <p class="post-excerpt">{{ post.excerpt }}</p>
          </div>
          <div class="post-footer">
            <span class="read-more">続きを読む <v-icon size="14">mdi-arrow-right</v-icon></span>
          </div>
        </router-link>
      </div>

      <p class="coming-soon reveal" v-reveal>
        随時更新中です。お楽しみに。
      </p>
    </v-container>
  </section>
</template>

<script>
import PageHero from "@/components/PageHero.vue";
import { blogPosts } from "@/constants/blogPosts";
import { formatMonthJa } from "@/utils/date";
import { vReveal } from "@/composables/useScrollReveal";

// 記事詳細から戻ってきたときの記事 id。beforeRouteEnter はインスタンス生成前に
// 走るので、ここに置いておけば初回描画から該当カードに view-transition-name が付き、
// 新スナップショット（router.afterEach の nextTick 直後）に間に合う
let returningFromId = null;

export default {
  name: "BlogView",
  components: { PageHero },
  directives: { reveal: vReveal },
  beforeRouteEnter(_to, from) {
    returningFromId = from.name === "blog-detail" ? from.params.id : null;
  },
  data: () => ({
    posts: blogPosts,
    // 共有要素トランジション（blog-cover）を付けるカードの記事 id。
    // 一覧 → 詳細はクリック時に、詳細 → 一覧は beforeRouteEnter の from から決める
    activeId: returningFromId,
  }),
  methods: {
    formatMonthJa,
  },
};
</script>

