  /* View Transition のスナップショットは親(.post-card)の overflow: hidden で
     切り抜かれず、この要素自身の形で撮られるので角丸を直接持たせる */
  border-radius: 20px 20px 0 0;
}
/* テーマ切替の円形ワイプ中は root に含めて一緒にワイプさせる（App.vue 参照） */
html.theme-switching .post-thumbnail {
  view-transition-name: none !important;
}

